class Solution {
    public boolean isNumber(String s) {
        boolean seenDigit = false;
        boolean seenDot = false;
        boolean seenExponent = false;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c >= '0' && c <= '9') {
                seenDigit = true;
            } else if (c == '.') {
                if (seenDot || seenExponent) {
                    return false;
                }
                seenDot = true;
            } else if (c == 'e' || c == 'E') {
                if (seenExponent || !seenDigit) {
                    return false;
                }
                seenExponent = true;
                seenDigit = false;
            } else if (c == '+' || c == '-') {
                if (i != 0 && s.charAt(i - 1) != 'e' && s.charAt(i - 1) != 'E') {
                    return false;
                }
            } else {
                return false;
            }
        }
        return seenDigit;
    }
}

class Solution {
    private static final int INVALID = -1;
    private static final int[][] TRANSITION = {
        {1, 2, 3, INVALID},
        {INVALID, 2, 3, INVALID},
        {INVALID, 2, 4, 5},
        {INVALID, 4, INVALID, INVALID},
        {INVALID, 4, INVALID, 5},
        {6, 7, INVALID, INVALID},
        {INVALID, 7, INVALID, INVALID},
        {INVALID, 7, INVALID, INVALID}
    };

    public boolean isNumber(String s) {
        int state = 0;
        for (int i = 0; i < s.length(); i++) {
            int type = classify(s.charAt(i));
            if (type == INVALID) {
                return false;
            }
            state = TRANSITION[state][type];
            if (state == INVALID) {
                return false;
            }
        }
        return state == 2 || state == 4 || state == 7;
    }

    private int classify(char c) {
        if (c == '+' || c == '-') {
            return 0;
        }
        if (c >= '0' && c <= '9') {
            return 1;
        }
        if (c == '.') {
            return 2;
        }
        if (c == 'e' || c == 'E') {
            return 3;
        }
        return INVALID;
    }
}

class Solution {
    public boolean isNumber(String s) {
        return s.matches("[+-]?((\\d+\\.?\\d*)|(\\.\\d+))([eE][+-]?\\d+)?");
    }
}

class Solution {
    public boolean isNumber(String s) {
        int exponent = findExponent(s);
        if (exponent == -2) {
            return false;
        }
        if (exponent >= 0) {
            return exponent > 0
                    && exponent + 1 < s.length()
                    && isDecimalOrInteger(s, 0, exponent)
                    && isInteger(s, exponent + 1, s.length());
        }
        return isDecimalOrInteger(s, 0, s.length());
    }

    private int findExponent(String s) {
        int found = -1;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == 'e' || c == 'E') {
                if (found != -1) {
                    return -2;
                }
                found = i;
            }
        }
        return found;
    }

    private boolean isDecimalOrInteger(String s, int left, int right) {
        if (left >= right) {
            return false;
        }
        if (s.charAt(left) == '+' || s.charAt(left) == '-') {
            left++;
        }
        boolean seenDigit = false;
        boolean seenDot = false;
        for (int i = left; i < right; i++) {
            char c = s.charAt(i);
            if (c >= '0' && c <= '9') {
                seenDigit = true;
            } else if (c == '.' && !seenDot) {
                seenDot = true;
            } else {
                return false;
            }
        }
        return seenDigit;
    }

    private boolean isInteger(String s, int left, int right) {
        if (left >= right) {
            return false;
        }
        if (s.charAt(left) == '+' || s.charAt(left) == '-') {
            left++;
        }
        if (left >= right) {
            return false;
        }
        for (int i = left; i < right; i++) {
            char c = s.charAt(i);
            if (c < '0' || c > '9') {
                return false;
            }
        }
        return true;
    }
}
